subprocess.run(compile_cmd, cwd=target, shell=True, check=True)
link_cmd = next(cmd for cmd in commands if " -o SkyRecompiled.app/SkyRecompiled " in cmd)
link_cmd = link_cmd.replace(obj, str(qa_obj)).replace(
    " -o SkyRecompiled.app/SkyRecompiled ", f" -o {app / 'SkyRecompiled'} ")
subprocess.run(link_cmd, cwd=target, shell=True, check=True)

